css:
/* --- Carried from the site template: the Chromium node-style re-arm rule and
   the footer's legal strip. Its header and utility-bar rules describe chrome
   this template does not have, so they are deliberately not carried. */
/* --- Node styles: re-arm them for Chromium ---------------------------------
   The renderer emits every node's own styles as `[data-bz-node="id"][data-bz-node]`,
   doubling the attribute to win on specificity. Past a certain stylesheet
   shape Chromium stops matching that form: the rules parse, they are in
   `document.styleSheets`, `el.matches()` on the same selector returns true —
   and the style engine never applies them. On the Press Kit page that meant
   every bordered card, on the page and inside its components alike, computed
   to no padding, no background and no border.
   One rule whose subject is the bare attribute restores all of them, and it
   has to live in this stylesheet: the site-wide Custom code block is a
   separate <style> and does not reach it, and a template's CSS is the only
   thing in this one that every page carries. The custom property it sets is
   inert — the rule exists only to be present. Worth reporting upstream: the
   renderer could emit `[data-bz-node="id"]:not(#_)` for the same specificity
   without the doubled attribute, and nothing downstream would have to know.
   =========================================================================== */
[data-bz-node] { --bz-node-styles: on; }

/* The footer band is the "Site footer" component; its rules travel with it.
   Only the legal strip below the content area is styled here. */
[data-bz-node="footer-legal"] { border-top: 1px solid #333; }

[data-bz-node="footer-legal"] p,
[data-bz-node="footer-legal"] .bz-navitem > a { color: #8A8A8A; font-size: 12px; }

/* The legal strip and the "Built by BuzzNerd" line that close the footer. */
[data-bz-node="footer-legal"] { background: var(--chrome); padding-block: 0 48px; }

[data-bz-node="footer-legal-row"] { border-top: 1px solid var(--chrome-line); padding-top: 24px; }

[data-bz-node="footer-copy"] p { font-size: 12px; line-height: 1.6; color: var(--chrome-label); margin: 0; }

[data-bz-node="footer-legal-nav"] .bz-nav { gap: 20px; }

[data-bz-node="footer-legal-nav"] .bz-navitem,
[data-bz-node="footer-legal-nav"] .bz-navitem > a { font-size: 12px; line-height: 1.6; font-weight: 400; color: var(--chrome-label); padding: 0; }

/* Desktop: copyright left, "Built by BuzzNerd" centred, legal links right, on
   one line. The outer tracks are equal so the middle one sits on the page's
   centre whatever the copy on either side measures. */
@media (min-width: 1101px) {
  [data-bz-node="footer-legal-row"] { grid-template-columns: 1fr auto 1fr; }
  [data-bz-node="footer-legal-row"] > .bz-col { grid-column: auto; }
}
/* Narrower, the three do not fit one line: copyright and legal links share it
   and the credit drops to its own centred line beneath, as before. */
@media (min-width: 641px) and (max-width: 1100px) {
  [data-bz-node="footer-legal-row"] > .bz-col { grid-column: span 6; }
  [data-bz-node="footer-legal-row"] > [data-bz-node="footer-built"] { grid-column: 1 / -1; }
}
@media (max-width: 1100px) {
  [data-bz-node="footer-legal-row"] { row-gap: 36px; }
  [data-bz-node="footer-built"] { order: 3; }
}
[data-bz-node="footer-built"] .bz-block { padding-block: 0; }

[data-bz-node="footer-built"] { display: flex; align-items: center; justify-content: center; gap: 8px; }

[data-bz-node="footer-built"] .bz-block { padding-block: 0; width: auto; }

[data-bz-node="footer-built-t"] p { color: #8A8A8A; font-size: 12px; margin: 0; }

[data-bz-node="footer-built-logo"] .bz-figure { margin: 0; }

/* The file carries a transparent margin so the bolt's tips and the TM are not
   clipped at the edge; 18px keeps the wordmark itself at the 16px it was. */
[data-bz-node="footer-built-logo"] img { height: 18px; width: auto; }

[data-bz-node="footer-legal-row"] { align-items: center; }

/* ===========================================================================
   New Home chrome — the brand site's floating navigation
   ---------------------------------------------------------------------------
   This stylesheet is loaded only on the pages this template wraps, and it wraps
   the "New Home" page alone, so nothing here can reach the live home page. Every
   rule is scoped to this template's own node ids.

   The brand site floats its navigation over the hero: the logo sits on the
   photograph at the left, the nav is a dark bar inset from the right, and the
   mega panel hangs directly under that bar, matching its width exactly. So the
   header is taken out of flow and laid over the page's first section rather
   than stacked above it, and the red utility bar the site template carries is
   not in this template at all.

   The panel is still the platform's: `main-nav` is a `menu` block with layout
   "mega" over the three-level "Main navigation - mega (New Home)" menu, so the
   columns, the hover and keyboard handling, the Escape key and the sub-1100px
   disclosure all come from the renderer. Nothing here is scripted.
   =========================================================================== */

/* --- The header, over the hero --------------------------------------------
   The only node in this template taken out of flow. It stays visible and
   selectable on the Design canvas because it is drawn on top of the hero, not
   hidden behind it — which is the check that matters for an absolute node. */
[data-bz-node="site-header"] {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 60;
  background: none;
  border: 0;
  padding-block: 24px;
  overflow: visible;
}
[data-bz-node="header-row"] {
  display: flex;
  align-items: center;
  gap: 24px;
  padding-inline: var(--container-pad);
  overflow: visible;
}
[data-bz-node="header-brand"] { flex: 0 0 auto; }
[data-bz-node="header-brand"] .bz-brand { display: flex; line-height: 0; }
[data-bz-node="site-header"] .bz-logo__img { height: 56px; width: auto; }

/* The bar. `position: relative` on it is what the panel hangs from, and that is
   the whole reason the panel comes out exactly as wide as the bar. */
[data-bz-node="header-bar"] {
  position: relative;
  flex: 0 0 auto;
  margin-left: auto;
  /* Measured off the reference: a warm near-black, not the site's colder
     --chrome (#141414). Kept literal because it is this template's own
     surface, not a token the rest of the site shares. */
  background: #272623;
  border-radius: 2px;
  padding: 0 4px;
  /* The panel below shares this element's left and right edges, so the bar's
     width is the panel's. It takes the room the logo leaves, up to the width
     the reference's own panel measures (1079px), and shrinks below that rather
     than overflowing on a narrow desktop. */
  flex: 0 0 auto;
}
[data-bz-node="header-bar-row"] {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 50px;
  overflow: visible;
}
[data-bz-node="header-nav"] { flex: 0 0 auto; min-width: 0; }
[data-bz-node="header-cta"] { flex: 0 0 auto; }
/* Items spread across the bar instead of bunching at one end, so the width the
   panel needs never shows up as a single empty pocket. */
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] {
  flex: 0 1 auto;
  flex-wrap: nowrap;
}
[data-bz-node="header-bar"] .bz-block { padding-block: 0; }
[data-bz-node="header-bar"] .bz-btns { margin-block: 0; }
[data-bz-node="header-cta"] .bz-btn {
  min-height: 38px;
  padding: 0 15px;
  gap: 8px;
  white-space: nowrap;
}

/* The first section of the page runs under the header, so its content needs
   clearance. The photograph behind it is meant to show through — that is the
   point of the overlay — only the copy moves. */
main > .bz-section:first-child { padding-top: calc(var(--bz-pad, var(--space-7)) + 96px); }

/* --- The bar's items -------------------------------------------------------
   Caps and tracked out, and the open item takes a lit chip with an accent rule
   under it — the brand site's tab treatment. Both are drawn inside the item's
   own box, so neither can change the bar's height. */
[data-bz-node="header-bar"] .bz-nav { gap: 2px; }
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a,
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > .bz-navlabel {
  position: relative;
  padding: 13px 15px;
  font: 500 13px/1.2 var(--font-body);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #FFFFFF;
  border-radius: 2px;
  transition: background-color 0.16s ease;
}
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a::before {
  content: "";
  position: absolute;
  left: 15px;
  right: 15px;
  /* 6px under the cap line, as the reference sets it — measured, not eyeballed. */
  bottom: 15px;
  height: 1px;
  background: #FFFFFF;
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 0.16s ease;
}
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:hover > a,
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:focus-within > a,
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem[data-open] > a {
  background: #41413E;
  color: #FFFFFF;
}
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:hover > a::before,
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:focus-within > a::before,
[data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem[data-open] > a::before {
  transform: scaleX(1);
}
@media (prefers-reduced-motion: reduce) {
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a,
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a::before { transition: none; }
}

@media (min-width: 1101px) {
  /* --- The panel ----------------------------------------------------------
     The site-wide rules in Design -> Custom code hang every mega panel off the
     nav list, because the platform's own `left: 50%` centres it on the item
     that owns it and a right-aligned bar then pushes it off the right edge.
     Here the bar itself is the containing block instead, which fixes that
     outright and is also what makes the panel and the bar share their edges.
     Worth reporting upstream — blocks.css could anchor a mega panel to the
     menu's own wrapper for everyone and drop the `left: 50%` entirely. */
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav,
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub { position: static; }

  /* The groups flow down one column and into the next, which is how the brand
     site's first column carries two headings and its second carries one.
     `display` is restated on all three open states because setting it here
     would otherwise out-specify the platform's own show/hide. */

  /* --- The gap between a trigger and its panel ----------------------------
     The panel hangs 9px below the trigger, and those 9px were dead ground:
     the pointer left the trigger, :hover dropped, and the panel closed before
     the pointer could reach it. A bridge across the gap keeps the pointer
     inside the item the whole way down.

     It is drawn on the panel, so it only exists while the panel is open, and
     it spans the panel rather than the trigger so a diagonal move towards a
     link on the far side is covered too. It stops exactly at the trigger's
     bottom edge — every trigger shares that edge at every desktop width — so
     it never sits over a neighbouring trigger and cannot swallow the hover
     that would open one. ::after already draws the panel's photograph. */
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav::before {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    top: -9px;
    height: 9px;
  }
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav {
    display: none;
    /* Anchored to the bar's right edge and given the reference panel's own
       width (1079px measured), rather than being tied to the bar's width. The
       bar is narrower than the reference's — six short labels where it has five
       long ones — and at the reference's 19px type a bar-width panel wraps half
       its links. Capped to the page gutters so it never overhangs. */
    left: 0;
    right: 0;
    top: calc(100% + 5px);
    transform: none;
    width: auto;
    min-width: 0;
    max-width: none;
    min-height: 320px;
    padding: 30px 260px 30px 32px;
    /* Stated rather than left to --card. The platform builds one site-wide
       /styles/chrome.css from the DEFAULT template's chrome and links it on
       every page, so its `[data-bz-node="site-header"] .bz-subnav {background:#fff}`
       reaches this template's header too — both templates name their header
       node `site-header`. The panel was white here by accident rather than by
       decision, which only showed up when the dark variant could not turn it
       off. Worth reporting upstream: a template's chrome CSS should not be
       served to pages that template does not wrap. */
    background: #FFFFFF;
    border: 0;
    box-shadow: 0 20px 46px rgba(0, 0, 0, 0.28);
    columns: 2;
    column-gap: 32px;
    border-radius: 2px;
  }
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub:hover > .bz-subnav,
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub:focus-within > .bz-subnav,
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub[data-open] > .bz-subnav {
    display: block;
  }
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav > .bz-navitem {
    display: block;
    width: auto;
    min-width: 0;
    break-inside: avoid;
    margin-bottom: 30px;
  }

  /* --- The photograph -------------------------------------------------------
     A background on a pseudo-element rather than on the panel, so it crops to
     fill instead of letterboxing, and so it stays out of the column flow and
     cannot affect the panel's hover area — the pointer has to stay inside the
     panel for it to remain open, and this sits inside it.

     The honest limit: this is a picture set in the template's Custom code, not
     an image block, because a `menu` block has nowhere to carry one. It is
     swapped here rather than picked from the media library. Worth reporting
     upstream — a mega item that could name a panel image would make the six
     rules below unnecessary and put the picture on the canvas, where a dealer
     could change it. */
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav::after {
    content: "";
    position: absolute;
    top: 50%;
    right: 30px;
    width: 200px;
    height: 200px;
    transform: translateY(-50%);
    background-color: var(--paper);
    background-position: center;
    background-size: cover;
    background-repeat: no-repeat;
    border-radius: 4px;
  }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:nth-child(1) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/41/whatsapp-image-2026-09-16-at-10.46.17-pm.jpeg"); /* Trucks */
  }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:nth-child(2) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/9b/whatsapp-image-2026-09-16-at-10.44.39-pm.jpeg"); /* Trailers & Bus */
  }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:nth-child(3) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/a8/sun-state-international-parts-counter-florida-scaled-1__02.jpg"); /* Parts */
  }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:nth-child(4) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/9e/commercial-truck-service-1-1.jpg"); /* Service */
  }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:nth-child(5) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/89/vision-action-oriented-2.jpg"); /* About */
  }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:nth-child(6) > .bz-subnav::after {
    background-image: url("https://vendure.buzznerdrv.com/assets/source/e2/whatsapp-image-2026-09-16-at-10.49.40-pm.jpeg"); /* Locations */
  }
}

/* --- Group headings --------------------------------------------------------
   Plain, bold and set in ink, with no rule under them: the brand site's panel
   is a page of links, not a table. Set in the body face on purpose — the
   display face (INTL Headline) draws caps whatever `text-transform` says, and
   these headings are mixed case. */
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav > .bz-navitem > .bz-navlabel {
  display: block;
  padding: 0;
  font: 700 1rem/30px var(--font-body);
  letter-spacing: 0;
  text-transform: capitalize;
  color: #000000;
}

/* --- The links under a heading ---------------------------------------------
   The nav block is set in caps for the bar; inside the panel the brand site
   sets them in sentence case, so that is undone here rather than on the node. */
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav { gap: 0; margin-top: 0; }
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a {
  display: block;
  padding: 0;
  font: 400 1rem/30px var(--font-body);
  letter-spacing: 0;
  text-transform: capitalize;
  color: #3B3C39;
  text-decoration: none;
}
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a:hover,
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a:focus-visible,
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a[aria-current="page"] {
  color: #3B3C39;
  text-decoration: underline;
  text-decoration-color: #000000;
  text-decoration-thickness: 2px;
  text-underline-offset: 6px;
}

/* --- Below 1100px ----------------------------------------------------------
   The platform turns the panel into the stacked disclosure behind the menu
   button. It wants none of the card chrome, a 268px photograph has nowhere to
   go on a phone, and two columns of links do not fit either. */
@media (min-width: 1101px) and (max-width: 1320px) {
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a { padding-inline: 9px; }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a::before { left: 9px; right: 9px; }
  [data-bz-node="site-header"] .bz-logo__img { height: 46px; }
}

@media (max-width: 1100px) {
  [data-bz-node="header-bar"] { max-width: none; padding: 0 12px; }
  [data-bz-node="header-bar-row"] { min-height: 52px; }
  [data-bz-node="site-header"] .bz-logo__img { height: 40px; }
  [data-bz-node="site-header"] .bz-menu-toggle { border-color: #444; color: var(--chrome-text); }
  /* The panel is positioned against the bar, and the bar is only as wide as the
     hamburger and the phone button beside it — 180px. A three-level menu drawn
     into 180px wraps "Brochures & Specifications" onto two lines and leaves
     half the screen empty. Dropping the bar out of the positioning chain hands
     the panel to the header band, which spans the screen, so it can be given
     the width of one. */
  [data-bz-node="header-bar"] { position: static; }
  [data-bz-node="header-bar"] .bz-menu-wrap[data-open] > .bz-menu {
    background: #fff;
    z-index: 60;
    left: auto;
    right: 12px;
    width: min(420px, calc(100vw - 24px));
    max-width: none;
    top: 84px;
    max-height: calc(100vh - 104px);
    overflow-y: auto;
  }
  /* The list sizes each row to its own label, which in a panel this wide leaves
     the trigger for "Parts" four characters wide. Stretching the rows gives the
     whole width of the drawer as the target. */
  [data-bz-node="header-bar"] .bz-menu-wrap[data-open] .bz-nav { align-items: stretch; }
  [data-bz-node="header-bar"] .bz-menu-wrap[data-open] .bz-navitem > a { color: var(--ink); }
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav {
    columns: auto;
    padding: 4px 0 16px;
    gap: 18px;
    box-shadow: none;
  }
  [data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav::after { display: none; }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a { padding: 9px 0; }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem > a::before { display: none; }
  [data-bz-node="header-bar"] [data-bz-menu="main-mega"] > .bz-navitem:hover > a { background: none; }
  [data-bz-node="header-cta"] .bz-btn { min-height: 38px; padding: 0 12px; }
  main > .bz-section:first-child { padding-top: calc(var(--bz-pad, var(--space-7)) + 64px); }
}


/* ===========================================================================
   Dark mode — this template only
   ---------------------------------------------------------------------------
   Loaded only on the pages this template wraps, which is "New Home Dark"
   alone. The chrome is the New Home header unchanged: the same floating bar,
   the same "Main navigation - mega (New Home)" menu, the same platform mega
   panel. Only the surfaces below it change.

   The page's structure is not touched. Its bands still ask for `paper`, `card`
   and `ink` in the same rhythm they always did — what changes is what those
   three words mean. That is the whole of the dark mode: invert the palette,
   keep the design. A dealer moving a band from "paper" to "card" on the canvas
   still gets a sensible dark surface, because the tokens carry the theme and
   the nodes carry the layout.

   Three tones, deepest to lightest: an `ink` band at #0F0F0F, the page at
   #1A1A1A, a `card` band at #232323. The light build's rhythm survives intact.
   =========================================================================== */

body {
  /* The palette, inverted. --ink stops being a surface here and becomes the
     text colour, which is what almost every rule in blocks.css and in the
     site's own layer actually uses it for; the handful that paint with it are
     repointed below. */
  --paper: #1A1A1A;
  --card: #232323;
  --ink: #EDEDED;
  --ink-dark: #FFFFFF;
  --line: #333333;
  --muted: #9A9A9A;
  --body-text: #C7C1B4;
  /* The site layer sets body's colour as a literal, so the token alone cannot
     reach it. */
  color: #EDEDED;
  background: #141414;
}

/* --- Where --ink was a surface, not a colour ------------------------------- */
.bz-section--bg-ink,
.bz-col--bg-ink { background: #0F0F0F; }
.bz-block--statBand .bz-stat { background: #0F0F0F; }
.bz-video { background: #0F0F0F; }
/* A section with no background of its own sits straight on the page. */
main { background: #1A1A1A; }

/* --- Literals in the site's own layer that assume a light page ------------- */
.bz-lede { color: var(--body-text); }
.bz-quote blockquote { color: var(--body-text); }
.bz-quote__n { color: var(--ink); }
.bz-block p { color: var(--body-text); }
.bz-section--bg-card p,
.bz-section--bg-paper p { color: var(--body-text); }
.bz-block :is(h1, h2, h3, h4, h5, h6) { color: var(--ink); }
.bz-stat__v { color: var(--ink); }

/* Form controls read as wells cut into the page rather than as white cards. */
.bz-input,
.bz-field select,
.bz-field textarea { background: #141414; color: var(--ink); border-color: var(--line); }
.bz-input::placeholder,
.bz-field textarea::placeholder { color: #7A7A7A; }

/* The placeholder art ships as a real image so each photo stays a replaceable
   image block; on a dark page its light fill is the one thing that gives it
   away as a placeholder. */
img[src$="photo-placeholder.svg"] { background: #2A2A2A; }

/* --- The mega panel --------------------------------------------------------
   blocks.css paints the panel with --card, so it follows the palette on its
   own. What does not follow are the three literals measured off the reference,
   which are all set for ink on white. */
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav > .bz-navitem > .bz-navlabel {
  color: #FFFFFF;
}
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a { color: #B9B9B9; }
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a:hover,
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a:focus-visible,
[data-bz-node="header-bar"] .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a[aria-current="page"] {
  color: #FFFFFF;
  text-decoration-color: #FFFFFF;
}
/* On a dark panel the reference's drop shadow does nothing, so the panel is
   separated from the photograph behind it by a hairline instead. */
[data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav {
  background: #1C1C1C;
  border: 1px solid #383838;
  box-shadow: 0 20px 46px rgba(0, 0, 0, 0.55);
}
/* The photograph's backing colour while it loads, and the collapsed nav panel
   on a phone — both are stated light in the base template. */
[data-bz-node="header-bar"] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav::after {
  background-color: #2A2A2A;
}
@media (max-width: 1100px) {
  [data-bz-node="header-bar"] .bz-menu-wrap[data-open] > .bz-menu { background: #1C1C1C; }
  [data-bz-node="header-bar"] .bz-menu-wrap[data-open] .bz-navitem > a { color: #EDEDED; }
}


/* --- Buttons ---------------------------------------------------------------
   The site design layer draws every button with a hard 0 edge. These pages
   round them instead — the header's phone CTA, the hero's, and every button
   inside the page's bands and its footer. */
.bz-btn { border-radius: 8px; }

/* The "Choose a type" rail is a shared component and styles its own buttons —
   10px on the Buy Now CTAs, a 50% circle on its carousel arrows — so a plain
   .bz-btn rule does not reach them. Overridden here rather than in the
   component, which other pages place too. The `main` prefix is what wins on
   specificity; the component's rules are otherwise identical in weight. */
main [data-bz-section="type-rail"] [data-bz-node^="tr-slide-cta"] .bz-btn,
main [data-bz-section="type-rail"] [data-bz-node="tr-nav"] .bz-btn { border-radius: 8px; }

@media (max-width: 640px) {
  /* The legal strip sets padding: 0 on its links, which leaves them 19px tall —
     the smallest targets left on the site. Height rather than an overhanging hit
     area, because they sit in a row and would otherwise overlap each other. */
  [data-bz-node="footer-legal-nav"] .bz-navitem > a { display: block; padding-block: 10px; }
  /* The legal links are set to the right of the copyright line, which the menu
     block carries as bz-menu--end on its own wrapper rather than on the list.
     Stacked, that right edge leaves them starting 106px in from everything else
     in the footer. */
  [data-bz-node="footer-legal-nav"] .bz-nav { gap: 8px 20px; }
  [data-bz-node="footer-legal-nav"] .bz-menu { justify-content: flex-start; }
}

/* --- Phone: the header row has a floor wider than the screen -----------------
   The row never stacks, so its two columns keep their natural widths: the
   lockup is 4.1:1, so at 40px tall it is 164px, and the bar holding the
   hamburger and the phone button is 180px. With the gutters that is a 416px
   floor — wider than every phone sold, so the bar was pushed off the right
   edge and the page scrolled sideways under it.

   Grid items refuse to shrink below their content by default. The brand column
   is released and the lockup scales into whatever the bar leaves. */
@media (max-width: 640px) {
  /* The row carries 48px gutters, a quarter of a phone's width, and they do not
     even line up with the 20px the page's own containers use — so the lockup sat
     inset from the copy beneath it. Matching the page gutter buys back 56px,
     which is most of what the row was short. */
  [data-bz-node="header-row"] { padding-inline: 20px; gap: 12px; }
  [data-bz-node="header-brand"] { min-width: 0; flex-shrink: 1; }
  [data-bz-node="site-header"] .bz-logo { max-width: 100%; display: block; }
  [data-bz-node="site-header"] .bz-logo__img {
    height: auto;
    max-height: 36px;
    max-width: 100%;
    width: auto;
  }
}
/* The lockup now shrinks to make room, so the row fits at any width and this
   is a legibility line rather than a fit one: sharing the row costs the lockup
   20px of width for every 20px of screen lost, and by 360px it is down to
   128x31 — the last size at which "International | Sun State" can still be
   read. Below that the number gives way instead. The hamburger stays, and
   Contact is one tap inside it. Every mainstream phone is 360 or wider, the
   375px iPhone SE and mini included, so in practice the number stays. */
@media (max-width: 359px) {
  [data-bz-node="header-cta"] { display: none; }
}

/* --- Sticky menu bar ------------------------------------------------------
   The menu bar stays pinned to the top of the window on every page, the way
   the International brand site's does; the logo and the header band scroll
   away with the page. The platform's `scrollstate` behaviour on the header
   marks it [data-bz-scrolled] the moment the page moves, and only then is the
   bar taken out to `position: fixed` — at exactly the place it already sits
   (measured per breakpoint below), so it never jumps. Without the script, and
   on the Design canvas, the header is simply its resting self. */
html {
  --sticky-bar-top: 27px;
  --sticky-bar-row: 56px;
  --sticky-bar-right: var(--container-pad);
  --sticky-bar-bottom: 77px;
  scroll-padding-top: calc(var(--sticky-bar-bottom) + 16px);
}
@media (min-width: 1101px) and (max-width: 1320px) {
  html { --sticky-bar-top: 24px; --sticky-bar-row: 50px; --sticky-bar-bottom: 74px; }
}
@media (max-width: 1100px) {
  html { --sticky-bar-top: 24px; --sticky-bar-row: 52px; --sticky-bar-bottom: 76px; }
}
@media (max-width: 640px) {
  html { --sticky-bar-top: 24px; --sticky-bar-row: 52px; --sticky-bar-right: 20px; --sticky-bar-bottom: 76px; }
}

/* Pinned: the bar leaves the header row for the window, at the same spot. The
   row keeps the bar's height so the header band never shrinks under it. */
[data-bz-node="site-header"][data-bz-scrolled] [data-bz-node="header-row"] {
  min-height: var(--sticky-bar-row);
}
[data-bz-node="site-header"][data-bz-scrolled] [data-bz-node="header-bar"] {
  position: fixed;
  top: var(--sticky-bar-top);
  right: var(--sticky-bar-right);
  z-index: 60;
}
/* Below 1101px the bar's drawer hangs from the header band, 84px from the top
   of the page. With the bar pinned the band has scrolled away, so the drawer is
   held at the same 84px from the top of the window instead — the place it
   opens at the top of the page — and keeps its own scroll for a long list. */
@media (max-width: 1100px) {
  [data-bz-node="site-header"][data-bz-scrolled] [data-bz-node="header-bar"] .bz-menu-wrap[data-open] > .bz-menu {
    position: fixed;
  }
}

/* Anything the page scrolls to — a post's contents links, an #anchor in a URL —
   lands below the pinned bar rather than under it, and the post's sticky
   contents rail parks beneath it instead of behind it. */
body [data-bz-node="art-side"] { top: calc(var(--sticky-bar-bottom) + 24px); }


/* ===========================================================================
   Mobile menu — below 1101px only
   ---------------------------------------------------------------------------
   Drawn the way the International brand site's mobile menu is: a full-screen
   dark sheet that slides in over the page, a close button at its top right,
   and the top-level items as full-width rows split by hairlines, with a plus
   on each item that opens a submenu. The page behind it stops scrolling, and
   the sheet scrolls on its own when the list is longer than the screen.

   Every rule here is inside max-width: 1100px, so the desktop bar and its mega
   panel are untouched. The open/close state is still the platform's own
   [data-open] on the menu wrapper; the template script adds the close button,
   the scroll lock and the accordion on top of it.
   =========================================================================== */
@media (max-width: 1100px) {
  /* The sheet is kept rendered while closed so it can slide both ways. It is
     hidden with visibility, which also takes it out of the tab order and away
     from screen readers exactly as display: none did. The doubled node id is
     what outranks the tablet-card geometry set above for the open state. */
  [data-bz-node="site-header"] [data-bz-node="header-bar"] .bz-menu-wrap > .bz-menu {
    display: flex;
    flex-direction: column;
    /* The block's "end" alignment would push the list to the foot of the sheet. */
    justify-content: flex-start;
    align-items: stretch;
    position: fixed;
    z-index: 70;
    inset: 0;
    top: 0;
    left: 0;
    right: 0;
    width: auto;
    max-width: none;
    height: 100vh;
    height: 100dvh;
    max-height: none;
    margin: 0;
    padding: 0;
    /* The bar's own surface, measured off the reference. */
    background: #272623;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    overflow-y: auto;
    /* The sheet scrolls on its own and never hands the gesture to the page. */
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    touch-action: pan-y;
    visibility: hidden;
    transform: translateX(100%);
    pointer-events: none;
    transition:
      transform 0.35s cubic-bezier(0.2, 0.7, 0.2, 1),
      visibility 0s linear 0.35s;
  }
  [data-bz-node="site-header"] [data-bz-node="header-bar"] .bz-menu-wrap[data-open] > .bz-menu {
    visibility: visible;
    transform: none;
    pointer-events: auto;
    transition:
      transform 0.35s cubic-bezier(0.2, 0.7, 0.2, 1),
      visibility 0s;
  }

  /* --- The sheet's head: the close button, top right ----------------------- */
  [data-bz-node="header-bar"] .bz-mnav-head {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    min-height: 68px;
    padding: 0 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }
  [data-bz-node="header-bar"] .bz-mnav-close {
    position: relative;
    width: 44px;
    height: 44px;
    padding: 0;
    background: none;
    border: 0;
    color: #FFFFFF;
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
  }
  [data-bz-node="header-bar"] .bz-mnav-close::before,
  [data-bz-node="header-bar"] .bz-mnav-close::after {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: 20px;
    height: 2px;
    margin: -1px 0 0 -10px;
    background: currentColor;
    transform: rotate(45deg);
  }
  [data-bz-node="header-bar"] .bz-mnav-close::after { transform: rotate(-45deg); }
  [data-bz-node="header-bar"] .bz-mnav-close:focus-visible { outline: 2px solid #FFFFFF; outline-offset: -4px; }

  /* --- The rows ------------------------------------------------------------ */
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-nav {
    flex: 0 0 auto;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    margin: 0;
    padding: 0;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem {
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  }
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem > a,
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem > .bz-navlabel {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 57px;
    padding: 0 20px;
    font: 700 12px/1.2 var(--font-body);
    letter-spacing: 0.03em;
    text-transform: uppercase;
    color: #FFFFFF;
    background: none;
    border-radius: 0;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem:hover > a,
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem:focus-within > a,
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem[data-open] > a {
    background: none;
    color: #FFFFFF;
  }

  /* The plus: two thin strokes, the upright one folding away to make a minus
     when the item is open. */
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem--has-sub > a { position: relative; padding-right: 48px; }
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem--has-sub > a::before,
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem--has-sub > a::after {
    content: "";
    display: block;
    position: absolute;
    left: auto;
    right: 20px;
    top: 50%;
    bottom: auto;
    width: 12px;
    height: 1px;
    margin-top: -0.5px;
    background: #BDBDB6;
    transform: none;
    transition: transform 0.25s ease;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem--has-sub > a::after { transform: rotate(90deg); }
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem--has-sub[data-open] > a::after,
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem--has-sub:focus-within > a::after {
    transform: rotate(0deg);
  }

  /* --- An open item's submenu, on the same dark sheet ---------------------- */
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav {
    position: static;
    width: auto;
    max-width: none;
    margin: 0;
    padding: 0 20px 20px;
    columns: auto;
    gap: 16px;
    background: none;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    transform: none;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap[data-open] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav {
    animation: bz-mnav-sub 0.25s ease;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-menu--mega .bz-subnav > .bz-navitem > .bz-navlabel {
    padding: 0;
    font: 700 12px/1.4 var(--font-body);
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: #8C8C85;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-menu--mega .bz-subnav .bz-subnav {
    position: static;
    margin: 6px 0 0;
    padding: 0;
    gap: 0;
    background: none;
    border: 0;
    box-shadow: none;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a {
    display: block;
    padding: 8px 0;
    font: 400 15px/1.35 var(--font-body);
    letter-spacing: 0;
    text-transform: capitalize;
    color: #E6E4DE;
    text-decoration: none;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a:hover,
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a:focus-visible,
  [data-bz-node="header-bar"] .bz-menu-wrap .bz-menu--mega .bz-subnav .bz-subnav > .bz-navitem > a[aria-current="page"] {
    color: #FFFFFF;
    text-decoration: underline;
    text-decoration-color: #FFFFFF;
    text-decoration-thickness: 1px;
    text-underline-offset: 4px;
  }

  /* The menu button itself is unchanged; while the sheet is open it sits under
     it, and the sheet's own close button stands in for it. */
  [data-bz-node="site-header"] .bz-menu-toggle {
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
  }
}
@keyframes bz-mnav-sub {
  from { opacity: 0; transform: translateY(-6px); }
  to { opacity: 1; transform: none; }
}

/* Set by the template script while the menu is open, and only below 1101px. */
@media (max-width: 1100px) {
  html.bz-mnav-locked,
  html.bz-mnav-locked body {
    overflow: hidden;
    overscroll-behavior: none;
  }
  html.bz-mnav-locked { scrollbar-gutter: stable; }
}

@media (prefers-reduced-motion: reduce) {
  [data-bz-node="site-header"] [data-bz-node="header-bar"] .bz-menu-wrap > .bz-menu,
  [data-bz-node="site-header"] [data-bz-node="header-bar"] .bz-menu-wrap[data-open] > .bz-menu,
  [data-bz-node="header-bar"] .bz-menu-wrap [data-bz-menu="main-mega"] > .bz-navitem--has-sub > a::after {
    transition: none;
  }
  [data-bz-node="header-bar"] .bz-menu-wrap[data-open] .bz-menu--mega .bz-nav > .bz-navitem--has-sub > .bz-subnav {
    animation: none;
  }
}

