/* Hold a mega panel open for a moment after the page scrolls.
 *
 * The panel is shown by :hover on its trigger and hidden with display:none, so
 * it cannot be held open with a transition delay — display does not animate.
 * The moment the page moves under the pointer the hover is lost and the panel
 * snaps shut mid-reach. The open rule already answers to [data-open] on the
 * trigger, so that is the hook used here: whichever item was open is pinned
 * open for a few seconds after a scroll, then released.
 *
 * The platform's dropdown behaviour was the first thing tried and does not fit:
 * this is the menu block's own chrome rather than a behaviour node, and none of
 * the eight behaviours takes a close delay. Header behaviour belongs in the
 * template's script, which is where this lives.
 *
 * Desktop only. Below 1101px the same markup is the collapsed drawer and the
 * platform's own chrome script owns data-open there.
 */
(function () {
  var HOLD_MS = 3000;    /* how long a panel stays up after the page moves */
  var GRACE_MS = 600;    /* let the pointer catch up before it can dismiss */
  var INTENT_MS = 350;   /* grace for a pointer that has slipped off the item */

  var desktop = window.matchMedia('(min-width: 1101px)');

  document.querySelectorAll('[data-bz-node="header-bar"] .bz-menu--mega').forEach(function (menu) {
    var items = Array.prototype.slice.call(menu.querySelectorAll('.bz-navitem--has-sub'));
    if (!items.length) return;

    var held = null;
    var timer = null;
    var mode = null;       /* 'scroll' or 'intent' — they are dismissed differently */
    var lastScroll = 0;

    function release() {
      if (timer) { clearTimeout(timer); timer = null; }
      /* Only ever clears the attribute this script set. */
      if (held) { held.removeAttribute('data-open'); held = null; }
      mode = null;
    }

    function hold(item, ms, why) {
      if (held && held !== item) held.removeAttribute('data-open');
      held = item;
      mode = why;
      item.setAttribute('data-open', '');
      if (timer) clearTimeout(timer);
      timer = setTimeout(release, ms);
    }

    function openItem() {
      for (var i = 0; i < items.length; i++) {
        if (items[i].matches(':hover')) return items[i];
      }
      return null;
    }

    window.addEventListener('scroll', function () {
      if (!desktop.matches) { release(); return; }
      lastScroll = Date.now();
      var item = openItem() || held;
      if (item) hold(item, HOLD_MS, 'scroll');
    }, { passive: true });

    /* Hover intent. The bridge in the stylesheet covers the 9px between a
       trigger and its panel, so a straight move down never leaves the item at
       all. This is for the rest: cutting the corner diagonally, or moving fast
       enough to land outside for a frame. Leaving an open item pins it briefly
       instead of closing it on the spot; coming back, or into its panel, hands
       it to :hover again, and moving on to another trigger drops it at once so
       that one opens without waiting. */
    items.forEach(function (item) {
      item.addEventListener('mouseleave', function () {
        if (!desktop.matches) return;
        if (item.matches(':hover') || (held && held !== item)) return;
        hold(item, INTENT_MS, 'intent');
      });
      item.addEventListener('mouseenter', function () {
        if (!desktop.matches) return;
        if (held === item) {
          if (timer) { clearTimeout(timer); timer = null; }  /* :hover owns it */
        } else if (held) {
          release();
        }
      });
    });

    /* Settling the pointer anywhere else closes it, once it has had a moment to
       catch up with the scroll. Back inside the item, hover owns it again. */
    document.addEventListener('mousemove', function (event) {
      if (!held) return;
      /* An intent hold is governed by its own short timer; the pointer being
         briefly nowhere is the very thing it exists to survive. */
      if (mode === 'intent') return;
      if (Date.now() - lastScroll < GRACE_MS) return;
      if (held.contains(event.target)) {
        if (timer) { clearTimeout(timer); timer = null; }
        return;
      }
      release();
    });

    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' || event.key === 'Esc') release();
    });

    if (desktop.addEventListener) desktop.addEventListener('change', release);
    else if (desktop.addListener) desktop.addListener(release);
  });
})();


/* Mobile menu — below 1101px only.
 *
 * The platform's chrome script owns the menu button: it flips [data-open] on
 * the menu wrapper and aria-expanded on the button, and on touch it makes the
 * first tap on a parent item open its submenu. This adds what the brand site's
 * mobile menu does on top of that:
 *
 *   - the menu is a full-screen sheet with its own close button at the top
 *     right, added here and only below 1101px, so the desktop DOM is untouched,
 *   - the page behind the open menu cannot scroll; the sheet still can,
 *   - Escape closes it, and keyboard focus stays inside it while it is open,
 *   - opening one submenu closes the others, so the list reads as an accordion,
 *   - page scrolling comes back the moment the menu closes, including when the
 *     window grows past 1100px or the page is restored from the back button.
 *
 * The "dropdown" and "drawer" behaviours were considered first, but the menu
 * button and panel are the menu block's own chrome rather than behaviour nodes,
 * and neither behaviour locks the page's scroll. Nothing here runs on desktop:
 * every handler checks the breakpoint, and above it the button is not shown.
 */
(function () {
  var mobile = window.matchMedia('(max-width: 1100px)');
  var root = document.documentElement;

  document.querySelectorAll('[data-bz-node="header-bar"] [data-bz-collapse]').forEach(function (wrap) {
    var toggle = wrap.querySelector('.bz-menu-toggle');
    var panel = wrap.querySelector(':scope > .bz-menu');
    if (!toggle || !panel) return;
    var topItems = Array.prototype.slice.call(
      panel.querySelectorAll('.bz-nav > .bz-navitem--has-sub'),
    );

    function isOpen() { return wrap.hasAttribute('data-open'); }

    /* The sheet's close button. Built here rather than in the menu data: it is
       part of the mobile chrome, not a destination a dealer edits. */
    var head = document.createElement('div');
    head.className = 'bz-mnav-head';
    var closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'bz-mnav-close';
    closeBtn.setAttribute('aria-label', 'Close menu');
    head.appendChild(closeBtn);
    closeBtn.addEventListener('click', function () { close(true); });
    function placeHead() {
      if (mobile.matches) {
        if (head.parentNode !== panel) panel.insertBefore(head, panel.firstChild);
      } else if (head.parentNode) {
        head.parentNode.removeChild(head);
      }
    }
    placeHead();

    function close(returnFocus) {
      if (!isOpen()) return;
      wrap.removeAttribute('data-open');
      toggle.setAttribute('aria-expanded', 'false');
      if (returnFocus) toggle.focus({ preventScroll: true });
    }

    /* Everything follows [data-open], whoever set it — the platform's button
       handler or close() above — so the lock can never be left behind. */
    function sync() {
      var open = isOpen() && mobile.matches;
      root.classList.toggle('bz-mnav-locked', open);
      if (open) {
        /* Every open starts collapsed and at the top of the list. */
        topItems.forEach(function (item) { item.removeAttribute('data-open'); });
        panel.scrollTop = 0;
        closeBtn.focus({ preventScroll: true });
      }
    }
    new MutationObserver(sync).observe(wrap, { attributes: true, attributeFilter: ['data-open'] });

    /* The sheet covers the screen, but a tap that still lands outside it — on
       a tablet in a browser with toolbars drawn over the page — closes it. */
    document.addEventListener('click', function (event) {
      if (!isOpen() || !mobile.matches) return;
      if (panel.contains(event.target) || toggle.contains(event.target)) return;
      event.preventDefault();
      event.stopPropagation();
      close(false);
    }, true);

    document.addEventListener('keydown', function (event) {
      if (event.key === 'Escape' && isOpen() && mobile.matches) close(true);
    });

    /* Tabbing off the end of the sheet would land on the page hidden under it. */
    document.addEventListener('focusin', function (event) {
      if (!isOpen() || !mobile.matches || panel.contains(event.target)) return;
      closeBtn.focus({ preventScroll: true });
    });

    /* Older iOS Safari still scrolls a page whose body is overflow: hidden. A
       drag that starts outside the panel is stopped here; inside it, the panel
       scrolls itself and overscroll-behavior keeps the gesture from chaining. */
    document.addEventListener('touchmove', function (event) {
      if (!isOpen() || !mobile.matches) return;
      if (panel.contains(event.target)) return;
      if (event.cancelable) event.preventDefault();
    }, { passive: false });

    /* The accordion: opening one parent closes its siblings. The platform's own
       handler runs first and decides whether this tap opens or follows. */
    panel.addEventListener('click', function (event) {
      if (!mobile.matches) return;
      /* A link that is being followed closes the menu, so an in-page #anchor
         lands on a page that can scroll to it. */
      var link = event.target.closest('a[href]');
      if (link && !event.defaultPrevented) { close(false); return; }
      var item = event.target.closest('.bz-nav > .bz-navitem--has-sub');
      if (!item || !item.hasAttribute('data-open')) return;
      topItems.forEach(function (other) {
        if (other !== item) other.removeAttribute('data-open');
      });
    });

    /* Growing past the breakpoint (a rotated tablet) or coming back to this page
       from the history must never leave the page locked. */
    var onChange = function () { if (!mobile.matches) close(false); placeHead(); sync(); };
    if (mobile.addEventListener) mobile.addEventListener('change', onChange);
    else if (mobile.addListener) mobile.addListener(onChange);
    window.addEventListener('pageshow', function (event) {
      if (event.persisted) close(false);
      sync();
    });
  });
})();
